-- IT Asset Management: category-based asset numbering for cPanel/MariaDB
-- Import this file once in phpMyAdmin after selecting the application's database.
-- Do not run it a second time after a successful import.
-- Existing asset numbers are preserved. New numbers are generated by the PHP application.

SET NAMES utf8mb4;

-- The application stores values such as LT0006 and DT0004.
ALTER TABLE `assetdata`
  MODIFY COLUMN `assetNum` varchar(30) NOT NULL;

ALTER TABLE `assetkat`
  ADD COLUMN `asset_prefix` varchar(6) NULL AFTER `Description`;

-- Friendly prefixes for the categories supplied with this application.
UPDATE `assetkat`
SET `asset_prefix` = CASE UPPER(`assetKat`)
  WHEN 'LAPTOP'    THEN 'LT'
  WHEN 'DESKTOP'   THEN 'DT'
  WHEN 'MONITOR'   THEN 'MN'
  WHEN 'PRINTER'   THEN 'PR'
  WHEN 'NETWORK'   THEN 'NW'
  WHEN 'SERVER'    THEN 'SV'
  WHEN 'STORAGE'   THEN 'ST'
  WHEN 'UPS'       THEN 'UPS'
  WHEN 'MOBILE'    THEN 'MB'
  WHEN 'TABLET'    THEN 'TB'
  WHEN 'PROJECTOR' THEN 'PJ'
  WHEN 'SCANNER'   THEN 'SC'
  WHEN 'CAMERA'    THEN 'CM'
  WHEN 'PHONE'     THEN 'PH'
  WHEN 'HEADSET'   THEN 'HS'
  WHEN 'KEYMOUSE'  THEN 'KM'
  WHEN 'DOCK'      THEN 'DK'
  WHEN 'ADAPTER'   THEN 'AD'
  WHEN 'DRIVE'     THEN 'DR'
  WHEN 'RACK'      THEN 'RK'
  WHEN 'FIREWALL'  THEN 'FW'
  WHEN 'BIOMETRIC' THEN 'BM'
  WHEN 'ACCESS'    THEN 'AC'
  WHEN 'MEETING'   THEN 'MR'
  WHEN 'OTHER'     THEN 'OT'
  -- Prefixes retained for the old numeric category identifiers, when present.
  WHEN '550001'    THEN 'L2'
  WHEN '550002'    THEN 'M2'
  WHEN '550003'    THEN 'P2'
  WHEN '550004'    THEN 'J2'
  WHEN '550005'    THEN 'R2'
  WHEN '550006'    THEN 'H2'
  WHEN '550007'    THEN 'C2'
  -- Deterministic collision-resistant fallback for any other existing category.
  ELSE CONCAT('X', UPPER(SUBSTRING(SHA1(`assetKat`),1,5)))
END
WHERE `asset_prefix` IS NULL OR TRIM(`asset_prefix`) = '';

ALTER TABLE `assetkat`
  MODIFY COLUMN `asset_prefix` varchar(6) NOT NULL;

ALTER TABLE `assetkat`
  ADD UNIQUE KEY `uq_assetkat_prefix` (`asset_prefix`);

-- Verification results shown by phpMyAdmin after a successful import.
SELECT `assetKat`, `Description`, `asset_prefix`
FROM `assetkat`
ORDER BY `Description`;

SELECT 'Category-prefix upgrade completed successfully.' AS `result`;
